 void StartSystemMonitor(){if(systemTimer!=null)return;systemTimer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(2)};systemTimer.Tick+=async delegate{await UpdateSystem();};systemTimer.Start();}
 async Task UpdateSystem(){bool visible=launcher!=null&&launcher.IsVisible&&activeTab=="System";if(systemBusy||!visible&&!cfg.SystemCpuTop&&!cfg.SystemMemoryTop&&!cfg.SystemDiskTop)return;systemBusy=true;try{var result=await Task.Run(()=>ReadSystem(visible));systemSample=result;Push(cpuHistory,result.Cpu);Push(memoryHistory,result.MemoryTotal>0?result.MemoryUsed/result.MemoryTotal*100:Double.NaN);Push(diskHistory,result.DiskTotal>0?result.DiskUsed/result.DiskTotal*100:Double.NaN);UpdateSystemLabels();if(launcher!=null&&launcher.IsVisible&&activeTab=="System"&&systemBody!=null)DrawSystemBody();}catch(Exception e){Log("System: "+e.Message);}finally{systemBusy=false;}}
 static void Push(List<double> series,double value){if(Double.IsNaN(value))return;series.Add(value);if(series.Count>40)series.RemoveAt(0);}
 SystemSample ReadSystem(bool appsNeeded){var result=new SystemSample();long idle,kernel,user;if(GetSystemTimes(out idle,out kernel,out user)){long total=kernel+user,delta=total-previousTotal;if(previousTotal>0&&delta>0)result.Cpu=Math.Max(0,Math.Min(100,100.0*(delta-(idle-previousIdle))/delta));previousIdle=idle;previousTotal=total;}var memory=new MemoryState();if(GlobalMemoryStatusEx(memory)){result.MemoryTotal=memory.Total;result.MemoryUsed=memory.Total-memory.Available;}try{var drive=new DriveInfo(System.IO.Path.GetPathRoot(Environment.SystemDirectory));result.Drive=drive.Name;result.DiskTotal=drive.TotalSize;result.DiskUsed=drive.TotalSize-drive.TotalFreeSpace;}catch{}
 if(appsNeeded){var now=DateTime.UtcNow;double elapsed=(now-sampleTime).TotalSeconds;var next=new Dictionary<int,AppSample>();int session;try{session=Process.GetCurrentProcess().SessionId;}catch{session=-1;}string systemFolder=Environment.SystemDirectory.TrimEnd('\\')+"\\";foreach(var process in Process.GetProcesses()){using(process){try{bool self=process.Id==selfPid;var item=new AppSample{Id=process.Id,Start=process.StartTime.ToUniversalTime().Ticks,Name=process.ProcessName,Window=process.MainWindowHandle,Memory=process.WorkingSet64};try{item.Path=process.MainModule.FileName;}catch{}try{item.CpuTicks=process.TotalProcessorTime.Ticks;AppSample prior=null;if(previousApps.TryGetValue(item.Id,out prior)&&prior.Start==item.Start&&elapsed>0)item.Cpu=Math.Max(0,Math.Min(100,(item.CpuTicks-prior.CpuTicks)/10000000.0/elapsed/Environment.ProcessorCount*100));IoState io;if(GetProcessIoCounters(process.Handle,out io)){item.IoValid=true;item.Bytes=io.ReadBytes+io.WriteBytes;if(prior!=null&&prior.Start==item.Start&&prior.IoValid&&elapsed>0&&item.Bytes>=prior.Bytes)item.Io=(item.Bytes-prior.Bytes)/elapsed;}}catch{}next[item.Id]=item;if(self)result.Self=item;else if(item.Window!=IntPtr.Zero)result.Apps.Add(item);else{bool sameSession=false;try{sameSession=process.SessionId==session;}catch{}bool systemProcess=String.IsNullOrEmpty(item.Path)||item.Path.StartsWith(systemFolder,StringComparison.OrdinalIgnoreCase);bool anotherAwl=String.Equals(item.Name,"Awl",StringComparison.OrdinalIgnoreCase);if(sameSession&&!systemProcess&&!anotherAwl)result.BackgroundApps.Add(item);}}catch{}}}previousApps=next;sampleTime=now;}return result;}
 string Percent(double value){return Double.IsNaN(value)?"—":value.ToString("0")+"%";}string Gigabytes(double value){return (value/1073741824.0).ToString("0.0")+" GB";}
 void SystemTopModules(){if(moduleViews==null||cpuTop!=null)return;cpuTop=Text("CPU —",12);memoryTop=Text("RAM —",12);diskTop=Text("Disk —",12);moduleViews["CPU"]=cpuTop;moduleViews["Memory"]=memoryTop;moduleViews["Disk space"]=diskTop;foreach(string name in new[]{"CPU","Memory","Disk space"})if(!cfg.ModuleOrder.Contains(name))cfg.ModuleOrder.Add(name);UpdateSystemLabels();}
 void UpdateSystemLabels(){if(cpuTop==null)return;cpuTop.Text="CPU "+Percent(systemSample.Cpu)+"  ";memoryTop.Text="RAM "+Gigabytes(systemSample.MemoryUsed)+"  ";diskTop.Text="Disk "+(systemSample.DiskTotal>0?Percent(systemSample.DiskUsed/systemSample.DiskTotal*100):"—")+"  ";cpuTop.Foreground=memoryTop.Foreground=diskTop.Foreground=ink;cpuTop.Visibility=cfg.SystemCpuTop&&!cfg.HiddenModules.Contains("CPU")?Visibility.Visible:Visibility.Collapsed;memoryTop.Visibility=cfg.SystemMemoryTop&&!cfg.HiddenModules.Contains("Memory")?Visibility.Visible:Visibility.Collapsed;diskTop.Visibility=cfg.SystemDiskTop&&!cfg.HiddenModules.Contains("Disk space")?Visibility.Visible:Visibility.Collapsed;}
