 FrameworkElement Spark(List<double> values){var canvas=new Canvas{Height=34,Margin=new Thickness(0,8,0,0)};Action draw=()=>{canvas.Children.Clear();if(values.Count<2)return;var line=new Polyline{Stroke=accentBrush,StrokeThickness=1.5};for(int i=0;i<values.Count;i++)line.Points.Add(new Point(i*Math.Max(1,canvas.ActualWidth)/(values.Count-1),32-Math.Max(0,Math.Min(100,values[i]))*.3));canvas.Children.Add(line);};canvas.SizeChanged+=delegate{draw();};return canvas;}
