 void DrawSystemBody(){if(systemBody==null)return;if(backgroundAppsScroll!=null)backgroundAppsOffset=backgroundAppsScroll.VerticalOffset;var old=page;page=systemBody;page.Children.Clear();var cards=new UniformGrid{Columns=3};var a=Metric("CPU",Percent(systemSample.Cpu),Environment.ProcessorCount+" logical processors",systemSample.Cpu,cpuHistory,cfg.SystemCpuTop,v=>cfg.SystemCpuTop=v);a.Margin=new Thickness(0,0,10,16);cards.Children.Add(a);var b=Metric("Memory",systemSample.MemoryTotal>0?Gigabytes(systemSample.MemoryUsed):"—",systemSample.MemoryTotal>0?Gigabytes(systemSample.MemoryTotal)+" total":"Unavailable",systemSample.MemoryTotal>0?systemSample.MemoryUsed/systemSample.MemoryTotal*100:0,memoryHistory,cfg.SystemMemoryTop,v=>cfg.SystemMemoryTop=v);b.Margin=new Thickness(0,0,10,16);cards.Children.Add(b);cards.Children.Add(Metric("Disk space",systemSample.DiskTotal>0?Gigabytes(systemSample.DiskUsed):"—",systemSample.Drive+" · "+Gigabytes(systemSample.DiskTotal-systemSample.DiskUsed)+" free",systemSample.DiskTotal>0?systemSample.DiskUsed/systemSample.DiskTotal*100:0,diskHistory,cfg.SystemDiskTop,v=>cfg.SystemDiskTop=v));page.Children.Add(cards);
 page.Children.Add(Card("",()=>{var heading=new DockPanel();var sort=new StackPanel{Orientation=Orientation.Horizontal};foreach(string key in new[]{"CPU","Memory","I/O","Name"}){string value=key;sort.Children.Add(Action(key,()=>{systemSort=value;cfg.SystemSort=value;SaveConfig();DrawSystemBody();},systemSort==key));}DockPanel.SetDock(sort,Dock.Right);heading.Children.Add(sort);heading.Children.Add(Text("Running apps   "+systemSample.Apps.Count,13));page.Children.Add(heading);page.Children.Add(ProcessRow(null));var rows=new StackPanel();foreach(var item in SortedSystemApps(systemSample.Apps,systemSort))rows.Children.Add(ProcessRow(item));if(systemSample.Apps.Count==0)rows.Children.Add(Text("No accessible running apps",12,mutedBrush));double rowsHeight=Math.Max(70,Math.Min(220,systemSample.Apps.Count*46+8));page.Children.Add(new ScrollViewer{Height=rowsHeight,Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Hidden,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});}));
 page.Children.Add(Card("",()=>{var heading=Text("Background apps   "+systemSample.BackgroundApps.Count,13);heading.FontWeight=FontWeights.SemiBold;page.Children.Add(heading);page.Children.Add(ProcessRow(null,true));var rows=new StackPanel();foreach(var item in SortedSystemApps(systemSample.BackgroundApps,systemSort))rows.Children.Add(ProcessRow(item,true));if(systemSample.BackgroundApps.Count==0)rows.Children.Add(Text("No manageable background apps",12,mutedBrush));double rowsHeight=Math.Max(62,Math.Min(180,systemSample.BackgroundApps.Count*46+8));backgroundAppsScroll=new ScrollViewer{Height=rowsHeight,Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Hidden,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};page.Children.Add(backgroundAppsScroll);Dispatcher.BeginInvoke(new Action(()=>{if(backgroundAppsScroll!=null)backgroundAppsScroll.ScrollToVerticalOffset(backgroundAppsOffset);}));}));
