 FrameworkElement RingGauge(string label,string value,double percent){percent=Math.Max(0,Math.Min(100,Double.IsNaN(percent)?0:percent));var stack=new StackPanel{HorizontalAlignment=HorizontalAlignment.Center};var canvas=new Canvas{Width=66,Height=66};canvas.Children.Add(new Ellipse{Width=56,Height=56,Margin=new Thickness(5),Stroke=cardBrush,StrokeThickness=6});double angle=Math.Min(359.8,percent*3.6),r=28,cx=33,cy=33;var start=new Point(cx,cy-r);double radians=(angle-90)*Math.PI/180;var end=new Point(cx+r*Math.Cos(radians),cy+r*Math.Sin(radians));var figure=new PathFigure{StartPoint=start,IsClosed=false};figure.Segments.Add(new ArcSegment{Point=end,Size=new Size(r,r),SweepDirection=SweepDirection.Clockwise,IsLargeArc=angle>180});canvas.Children.Add(new System.Windows.Shapes.Path{Data=new PathGeometry(new[]{figure}),Stroke=accentBrush,StrokeThickness=6,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round});var number=Text(value,10);number.FontWeight=FontWeights.SemiBold;number.TextAlignment=TextAlignment.Center;number.HorizontalAlignment=HorizontalAlignment.Center;number.VerticalAlignment=VerticalAlignment.Center;number.TextWrapping=TextWrapping.Wrap;var holder=new Border{Width=56,Height=56,Child=number};Canvas.SetLeft(holder,5);Canvas.SetTop(holder,5);canvas.Children.Add(holder);stack.Children.Add(canvas);var caption=Text(label,10,mutedBrush);caption.HorizontalAlignment=HorizontalAlignment.Center;caption.Margin=new Thickness(0,2,0,0);stack.Children.Add(caption);return stack;}
 FrameworkElement SelfUsageCard(){return Card("Awl usage",()=>{var item=systemSample.Self;var row=new Grid();for(int i=0;i<4;i++)row.ColumnDefinitions.Add(new ColumnDefinition());double cpu=item==null?0:item.Cpu,memoryPercent=item==null||systemSample.MemoryTotal<=0?0:item.Memory/systemSample.MemoryTotal*100,io=item==null||Double.IsNaN(item.Io)?0:item.Io/1048576.0;var gauges=new[]{RingGauge("CPU",item==null?"—":Percent(item.Cpu),cpu),RingGauge("Memory",item==null?"—":(item.Memory/1048576).ToString("0")+" MB",memoryPercent),RingGauge("Disk I/O",item==null||Double.IsNaN(item.Io)?"—":io.ToString("0.00")+" MB/s",Math.Min(100,io*10))};for(int i=0;i<gauges.Length;i++){Grid.SetColumn(gauges[i],i);row.Children.Add(gauges[i]);}var task=Action("Open Task Manager",()=>Process.Start(new ProcessStartInfo("taskmgr.exe"){UseShellExecute=true}));task.HorizontalAlignment=HorizontalAlignment.Center;task.VerticalAlignment=VerticalAlignment.Center;Grid.SetColumn(task,3);row.Children.Add(task);page.Children.Add(row);});}
 FrameworkElement ProcessRow(AppSample item,bool kill=false){var grid=new Grid{Margin=new Thickness(0,6,0,6)};grid.ColumnDefinitions.Add(new ColumnDefinition());foreach(double width in new[]{75.0,95.0,100.0,kill?58.0:32.0})grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(width)});if(item==null){string[] labels={"Process","CPU","Memory","I/O"};for(int i=0;i<labels.Length;i++){var text=Text(labels[i],11,mutedBrush);Grid.SetColumn(text,i);grid.Children.Add(text);}return grid;}var name=new StackPanel{Orientation=Orientation.Horizontal};var icon=new Image{Width=26,Height=26,Margin=new Thickness(0,0,10,0)};if(!String.IsNullOrEmpty(item.Path))QueueIcon(icon,item.Path);name.Children.Add(icon);var label=Text(item.Name,12);label.MaxWidth=240;label.TextWrapping=TextWrapping.NoWrap;label.TextTrimming=TextTrimming.CharacterEllipsis;label.ToolTip="PID "+item.Id;name.Children.Add(label);grid.Children.Add(name);string[] values={Percent(item.Cpu),Double.IsNaN(item.Memory)?"—":(item.Memory/1048576).ToString("0")+" MB",Double.IsNaN(item.Io)?"—":(item.Io/1048576).ToString("0.00")+" MB/s"};for(int i=0;i<3;i++){var text=Text(values[i],11,mutedBrush);Grid.SetColumn(text,i+1);grid.Children.Add(text);}var close=Action(kill?"Kill":"×",()=>{if(kill)KillSystemApp(item);else CloseSystemApp(item);});close.Padding=new Thickness(4);close.ToolTip=kill?"End background process":"Close app";Grid.SetColumn(close,4);grid.Children.Add(close);return new Border{BorderBrush=cardBrush,BorderThickness=new Thickness(0,0,0,1),Child=grid};}
 IEnumerable<AppSample> SortedSystemApps(IEnumerable<AppSample> source,string sort){if(sort=="CPU")return source.OrderByDescending(x=>Double.IsNaN(x.Cpu)?-1:x.Cpu).ThenBy(x=>x.Name);if(sort=="Memory")return source.OrderByDescending(x=>x.Memory).ThenBy(x=>x.Name);if(sort=="I/O")return source.OrderByDescending(x=>Double.IsNaN(x.Io)?-1:x.Io).ThenBy(x=>x.Name);return source.OrderBy(x=>x.Name,StringComparer.CurrentCultureIgnoreCase);}
 public string SystemSortSelfTest(){var values=new[]{new AppSample{Name="Zulu",Cpu=2,Memory=30,Io=8},new AppSample{Name="Alpha",Cpu=9,Memory=10,Io=3}};if(SortedSystemApps(values,"CPU").First().Name!="Alpha")return "FAILED: CPU order";if(SortedSystemApps(values,"Memory").First().Name!="Zulu")return "FAILED: memory order";if(SortedSystemApps(values,"I/O").First().Name!="Zulu")return "FAILED: I/O order";if(SortedSystemApps(values,"Name").First().Name!="Alpha")return "FAILED: name order";return "System CPU, memory, I/O, and name orders work";}
 void CloseSystemApp(AppSample item){try{using(var process=Process.GetProcessById(item.Id)){if(process.StartTime.ToUniversalTime().Ticks!=item.Start)return;if(!process.CloseMainWindow())MessageBox.Show(launcher,"This app did not accept a close request.","Close app");}}catch(ArgumentException){}catch(Exception e){MessageBox.Show(launcher,e.Message,"Unable to close app");}}
 void KillSystemApp(AppSample item){try{using(var process=Process.GetProcessById(item.Id)){if(process.StartTime.ToUniversalTime().Ticks!=item.Start)return;process.Kill();}}catch(ArgumentException){}catch(Exception e){MessageBox.Show(launcher,e.Message,"Unable to end background process");}}
} }
